import * as React from "react";
import { Select as SelectPrimitive } from "radix-ui";

import { useCollisionBoundary, usePortalContainer } from "../scope";

import { useFieldControlAttributes } from "../lib/field-context";
import { ListHighlight } from "../lib/list-highlight";
import { cn } from "../lib/utils";
import { Icon, type IconSource } from "./icon";
import type { FieldWidth } from "./input";
import { useMenuInset } from "./menu-inset";
import { Tooltip } from "./tooltip";

import controlStyles from "./controls.module.css";
import menu from "./menu.module.css";
import picker from "./picker.module.css";

const SelectSettingsContext = React.createContext<{
  wrap: boolean;
  descriptionLayout: "inline" | "stacked";
}>({ wrap: false, descriptionLayout: "inline" });

function titleIfTruncated(element: HTMLElement | null | undefined) {
  if (!element) return;
  const text = element.querySelector<HTMLElement>('[data-slot="option-text"]') ?? element;
  if (text.scrollWidth > text.clientWidth || element.scrollWidth > element.clientWidth)
    element.title = text.textContent ?? "";
  else element.removeAttribute("title");
}

const SelectNameContext = React.createContext<{
  "aria-label"?: string;
  "aria-labelledby"?: string;
  disabledReason?: string;
}>({});

export type SelectOption = {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
  group?: string;
  /** A Badge after the label, in the menu row and in the trigger while this option is selected, such as "Current". */
  badge?: React.ReactNode;
};
function Select({
  options,
  label,
  placeholder = "Choose an option",
  size,
  width,
  invalid,
  align = "start",
  menuWidth,
  icon,
  wrap,
  descriptionLayout = "inline",
  disabledReason,
  disabled,
  onChange,
  onValueChange,
  children,
  id,
  "aria-describedby": describedBy,
  "aria-label": ariaLabel,
  "aria-labelledby": labelledBy,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Root> & {
  options?: readonly SelectOption[];
  label?: string;
  placeholder?: string;
  size?: "sm" | "default" | "md" | "lg";
  /** A fixed token width for the trigger that doesn't shrink. Unset fills the row. */
  width?: FieldWidth;
  invalid?: boolean;
  align?: "start" | "center" | "end";
  menuWidth?: React.CSSProperties["width"];
  /** A glyph at the trigger's start, such as the kind of value it picks. */
  icon?: IconSource;
  /** Wrap long option labels in the list instead of truncating them. The trigger stays on one line. */
  wrap?: boolean;
  /** inline puts an option's description after its label on one line; stacked puts it on the lines below, wrapping in full, for descriptions longer than a few words such as what a role allows. */
  descriptionLayout?: "inline" | "stacked";
  /** Blocks choosing and says why: the trigger looks disabled but stays focusable, shows the reason in a tooltip on hover and focus, and exposes it as the accessible description. */
  disabledReason?: string;
  onChange?: (value: string) => void;
  id?: string;
  "aria-describedby"?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
}) {
  const groups = [...new Set(options?.map((option) => option.group ?? ""))];
  return (
    <SelectPrimitive.Root
      data-slot="select"
      onValueChange={(value) => {
        onValueChange?.(value);
        onChange?.(value);
      }}
      disabled={disabledReason ? undefined : disabled}
      {...props}
    >
      <SelectSettingsContext value={{ wrap: wrap ?? false, descriptionLayout }}>
        {options ? (
          <>
            <SelectTrigger
              id={id}
              size={size ?? "default"}
              icon={icon}
              width={width}
              disabledReason={disabledReason}
              aria-label={ariaLabel ?? label}
              aria-labelledby={labelledBy}
              aria-describedby={describedBy}
              aria-invalid={invalid || undefined}
            >
              <SelectValue placeholder={placeholder} />
            </SelectTrigger>
            <SelectContent
              align={align}
              style={
                menuWidth
                  ? { width: menuWidth, maxWidth: "var(--radix-select-content-available-width)" }
                  : undefined
              }
            >
              {groups.map((group) => (
                <SelectGroup key={group}>
                  {group && <SelectLabel>{group}</SelectLabel>}
                  {options
                    .filter((option) => (option.group ?? "") === group)
                    .map((option) => (
                      <SelectItem
                        key={option.value}
                        value={option.value}
                        disabled={option.disabled}
                        description={option.description}
                        badge={option.badge}
                      >
                        <span data-slot="select-option-label">{option.label}</span>
                      </SelectItem>
                    ))}
                </SelectGroup>
              ))}
            </SelectContent>
          </>
        ) : (
          <SelectNameContext
            value={{ "aria-label": ariaLabel, "aria-labelledby": labelledBy, disabledReason }}
          >
            {children}
          </SelectNameContext>
        )}
      </SelectSettingsContext>
    </SelectPrimitive.Root>
  );
}

function SelectGroup({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Group>) {
  return (
    <SelectPrimitive.Group ref={ref} data-slot="select-group" className={className} {...props} />
  );
}
SelectGroup.displayName = "SelectGroup";

function SelectValue({ ref, ...props }: React.ComponentProps<typeof SelectPrimitive.Value>) {
  return <SelectPrimitive.Value ref={ref} data-slot="select-value" {...props} />;
}
SelectValue.displayName = "SelectValue";

function SelectTrigger({
  className,
  size = "default",
  icon,
  width,
  disabledReason,
  children,
  onPointerEnter,
  onFocus,
  onPointerDown,
  onClick,
  onKeyDown,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger> & {
  size?: "sm" | "default" | "md" | "lg";
  icon?: IconSource;
  /** A fixed token width that doesn't shrink. Unset fills the row. */
  width?: FieldWidth;
  /** Blocks choosing and says why: the trigger looks disabled but stays focusable, shows the reason in a tooltip on hover and focus, and exposes it as the accessible description. */
  disabledReason?: string;
} & { ref?: React.Ref<React.ComponentRef<typeof SelectPrimitive.Trigger>> }) {
  const name = React.useContext(SelectNameContext);
  const fieldAttributes = useFieldControlAttributes({
    ...props,
    "aria-labelledby": props["aria-labelledby"] ?? name["aria-labelledby"]
  });
  const reasonId = React.useId();
  const reason = (disabledReason ?? name.disabledReason) || undefined;
  const trigger = (
    <SelectPrimitive.Trigger
      ref={ref}
      data-slot="select-trigger"
      data-size={size}
      data-width={width}
      className={cn(
        controlStyles.field,
        controlStyles.trigger,
        controlStyles.triggerHover,
        "[&_svg]:pointer-events-none [&_svg]:shrink-0",
        controlStyles.selectTrigger,
        className
      )}
      aria-label={name["aria-label"]}
      onPointerEnter={(event) => {
        onPointerEnter?.(event);
        titleIfTruncated(
          event.currentTarget.querySelector<HTMLElement>('[data-slot="select-value"]')
        );
      }}
      onFocus={(event) => {
        onFocus?.(event);
        titleIfTruncated(
          event.currentTarget.querySelector<HTMLElement>('[data-slot="select-value"]')
        );
      }}
      {...props}
      {...fieldAttributes}
      disabled={reason ? undefined : props.disabled}
      aria-disabled={reason ? true : props["aria-disabled"]}
      aria-describedby={
        [fieldAttributes["aria-describedby"], reason && reasonId].filter(Boolean).join(" ") ||
        undefined
      }
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (reason) event.preventDefault();
      }}
      onClick={(event) => {
        onClick?.(event);
        if (reason) event.preventDefault();
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        const typeahead =
          event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey;
        if (reason && (typeahead || ["Enter", "ArrowUp", "ArrowDown"].includes(event.key)))
          event.preventDefault();
      }}
    >
      {icon && (
        <span className={controlStyles.leading} data-slot="select-icon">
          <Icon icon={icon} />
        </span>
      )}
      {children}
      <SelectPrimitive.Icon asChild>
        <Icon name="chev-down" className={controlStyles.chevron} />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
  if (!reason) return trigger;
  return (
    <>
      <Tooltip content={reason}>{trigger}</Tooltip>
      <span id={reasonId} className="sr-only">
        {reason}
      </span>
    </>
  );
}
SelectTrigger.displayName = "SelectTrigger";

function SelectContent({
  className,
  collisionPadding = 8,
  children,
  align = "start",
  sideOffset = 4,
  style,
  wrap,
  descriptionLayout,
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content>, "position"> & {
  /** Wrap long option labels instead of truncating them. Defaults to the Select's `wrap`; items can override it. */
  wrap?: boolean;
  /** Where option descriptions go: after the label on one line, or stacked below it and wrapping in full. Defaults to the Select's descriptionLayout. */
  descriptionLayout?: "inline" | "stacked";
  ref?: React.Ref<React.ComponentRef<typeof SelectPrimitive.Content>>;
}) {
  const inset = useMenuInset<HTMLDivElement>();
  const inherited = React.useContext(SelectSettingsContext);
  return (
    <SelectPrimitive.Portal container={usePortalContainer()}>
      <SelectPrimitive.Content
        ref={ref}
        data-slot="select-content"
        collisionPadding={collisionPadding}
        collisionBoundary={useCollisionBoundary()}
        className={cn("relative z-50", menu.surface, menu.panel, menu.motion, className)}
        position="popper"
        align={align}
        sideOffset={sideOffset}
        style={{ width: "var(--radix-select-trigger-width)", ...style }}
        {...props}
      >
        <SelectScrollUpButton />
        <SelectPrimitive.Viewport ref={inset} className={menu.inset} data-scroll-fade="y">
          <SelectSettingsContext
            value={{
              wrap: wrap ?? inherited.wrap,
              descriptionLayout: descriptionLayout ?? inherited.descriptionLayout
            }}
          >
            {children}
          </SelectSettingsContext>
          <ListHighlight />
        </SelectPrimitive.Viewport>
        <SelectScrollDownButton />
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
}
SelectContent.displayName = "SelectContent";

function SelectLabel({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Label>) {
  return (
    <SelectPrimitive.Label
      ref={ref}
      data-slot="select-label"
      className={cn(menu.label, className)}
      {...props}
    />
  );
}
SelectLabel.displayName = "SelectLabel";

function SelectItem({
  className,
  children,
  description,
  badge,
  wrap,
  onFocus,
  "aria-describedby": describedBy,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item> & {
  description?: string;
  /** A Badge after the label, shown in the menu row and in the trigger while this item is selected. The label truncates before the badge does. */
  badge?: React.ReactNode;
  /** Wrap this label instead of truncating it. Defaults to the content's `wrap`. */
  wrap?: boolean;
} & {
  ref?: React.Ref<React.ComponentRef<typeof SelectPrimitive.Item>>;
}) {
  const descriptionId = React.useId();
  const label = React.useRef<HTMLSpanElement>(null);
  const inherited = React.useContext(SelectSettingsContext);
  const wrapped = wrap ?? inherited.wrap;
  const stacked = inherited.descriptionLayout === "stacked" && Boolean(description);
  React.useLayoutEffect(() => {
    const node = label.current;
    if (node?.title && node.title !== node.textContent) titleIfTruncated(node);
  });
  const labelText = (
    <span
      ref={label}
      className={picker.optionLabel}
      onPointerEnter={(event) => titleIfTruncated(event.currentTarget)}
    >
      <SelectPrimitive.ItemText>
        {badge === undefined ? (
          children
        ) : (
          <>
            <span data-slot="option-text">{children}</span>
            {badge}
          </>
        )}
      </SelectPrimitive.ItemText>
    </span>
  );
  return (
    <SelectPrimitive.Item
      ref={ref}
      data-slot="select-item"
      aria-describedby={
        [describedBy, description ? descriptionId : undefined].filter(Boolean).join(" ") ||
        undefined
      }
      data-wrap={wrapped || undefined}
      data-description={stacked ? "stacked" : undefined}
      className={cn(menu.row, picker.option, className)}
      onFocus={(event) => {
        onFocus?.(event);
        titleIfTruncated(label.current);
      }}
      {...props}
    >
      {stacked ? (
        <span className={menu.text}>
          {labelText}
          <span id={descriptionId} className={cn(menu.description, picker.optionDescription)}>
            {description}
          </span>
        </span>
      ) : (
        <>
          {labelText}
          {description && (
            <span id={descriptionId} className={picker.optionMeta}>
              {description}
            </span>
          )}
        </>
      )}
      <span className={picker.optionCheck}>
        <SelectPrimitive.ItemIndicator>
          <Icon name="check" />
        </SelectPrimitive.ItemIndicator>
      </span>
    </SelectPrimitive.Item>
  );
}
SelectItem.displayName = "SelectItem";

function SelectSeparator({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Separator>) {
  return (
    <SelectPrimitive.Separator
      ref={ref}
      data-slot="select-separator"
      className={cn(menu.separator, className)}
      {...props}
    />
  );
}
SelectSeparator.displayName = "SelectSeparator";

function SelectScrollUpButton({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.ScrollUpButton>) {
  return (
    <SelectPrimitive.ScrollUpButton
      ref={ref}
      data-slot="select-scroll-up-button"
      className={cn(
        "z-10 flex cursor-default items-center justify-center bg-popover py-1 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      <Icon name="chev-down" className="rotate-180" />
    </SelectPrimitive.ScrollUpButton>
  );
}
SelectScrollUpButton.displayName = "SelectScrollUpButton";

function SelectScrollDownButton({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.ScrollDownButton>) {
  return (
    <SelectPrimitive.ScrollDownButton
      ref={ref}
      data-slot="select-scroll-down-button"
      className={cn(
        "z-10 flex cursor-default items-center justify-center bg-popover py-1 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      <Icon name="chev-down" />
    </SelectPrimitive.ScrollDownButton>
  );
}
SelectScrollDownButton.displayName = "SelectScrollDownButton";

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue
};

.field {
  --cipher-field-height: var(--cipher-size-control-default);
  --cipher-field-inline: var(--cipher-space-control-inline-sm);
  --cipher-field-nested: calc(
    var(--cipher-field-height) - 2 *
      (var(--cipher-space-control-slot-inset) + var(--cipher-size-control-border))
  );
  box-sizing: border-box;
  min-height: var(--cipher-field-height);
  padding-block: calc(
    (var(--cipher-field-height) - var(--cipher-type-body-line-height)) / 2 -
      var(--cipher-size-control-border)
  );
  padding-inline: var(--cipher-field-inline);
  border: var(--cipher-size-control-border) solid var(--cipher-control);
  border-radius: 0;
  background-color: var(--cipher-control-surface);
  color: var(--cipher-ink);
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  outline: none;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-fade);
}
.field[data-size="xs"] {
  --cipher-field-height: var(--cipher-size-control-xs);
  --cipher-field-inline: var(--cipher-space-6);
  --cipher-field-nested: calc(
    var(--cipher-size-control-xs) - 2 *
      (var(--cipher-space-control-slot-inset) + var(--cipher-size-control-border))
  );
  padding-block: calc(
    (var(--cipher-field-height) - var(--cipher-type-caption-line-height)) / 2 -
      var(--cipher-size-control-border)
  );
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
}
.field[data-size="xs"]:is(.fieldBox, .inputGroup) {
  padding-block: 0;
}
.field[data-size="xs"] .leading > svg {
  width: var(--cipher-size-icon-xs);
  height: var(--cipher-size-icon-xs);
}
.field[data-size="md"] {
  --cipher-field-height: var(--cipher-size-control-md);
  --cipher-field-inline: var(--cipher-space-control-inline-md);
  --cipher-field-nested: var(--cipher-size-nested-md);
}
.field[data-size="lg"] {
  --cipher-field-height: var(--cipher-size-control-lg);
  --cipher-field-inline: var(--cipher-space-control-inline);
  --cipher-field-nested: var(--cipher-size-nested-lg);
}
.field[data-width] {
  flex-shrink: 0;
  max-width: 100%;
}
.field[data-width="xs"] {
  width: var(--cipher-size-field-xs);
}
.field[data-width="sm"] {
  width: var(--cipher-size-field-sm);
}
.field[data-width="md"] {
  width: var(--cipher-size-field-md);
}
.field::placeholder,
.field ::placeholder {
  color: var(--cipher-muted);
}
@media (hover: hover) {
  .field:hover:not(:disabled, [aria-disabled="true"], [data-control-disabled]) {
    background-color: var(--cipher-control-surface-hover);
  }
}
.field:is(:focus-visible, [aria-expanded="true"]),
.field[data-field-box][data-control-focus] {
  border-color: var(--cipher-ink);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
.field:is([aria-invalid="true"], [data-invalid]),
.field[data-field-box][data-control-invalid] {
  border-color: var(--cipher-control-invalid-border);
}
.field:is([aria-invalid="true"], [data-invalid]):is(:focus-visible, [aria-expanded="true"]),
.field:is([aria-invalid="true"], [data-invalid])[data-field-box][data-control-input-focus],
.field[data-field-box][data-control-invalid][data-control-invalid-focus] {
  border-color: var(--cipher-bad);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring-bad);
}
.field:is(:disabled, [aria-disabled="true"]),
.field[data-field-box][data-control-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.field:is([readonly]:not([aria-disabled="true"]), [data-field-box][data-control-readonly]) {
  background-color: var(--cipher-paper);
}
.field:is([readonly]:not([aria-disabled="true"]), [data-field-box][data-control-readonly]),
.bare[readonly]:not([aria-disabled="true"]) {
  cursor: default;
}
.field[readonly],
.bare[readonly] {
  caret-color: transparent;
}
.fieldBox {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: var(--cipher-space-control-gap);
  padding-block: 0;
  cursor: text;
}
.fieldBox[data-trailing] {
  --cipher-kbd-host-block: calc(var(--cipher-field-height) - 2 * var(--cipher-size-control-border));
  --cipher-kbd-host-end: var(--cipher-space-control-slot-inset);
  padding-inline-end: var(--cipher-space-control-slot-inset);
}
.bare {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  min-height: calc(var(--cipher-field-height) - 2 * var(--cipher-size-control-border));
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
}
input:is(.field, .bare)[type="number"] {
  appearance: textfield;
  -moz-appearance: textfield;
}
input:is(.field, .bare)[type="number"]::-webkit-inner-spin-button,
input:is(.field, .bare)[type="number"]::-webkit-outer-spin-button {
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
}
.bare:disabled {
  cursor: not-allowed;
}
.mono {
  font-family: var(--cipher-font-mono, monospace);
}
.leading,
.chevron {
  display: inline-flex;
  flex: none;
  color: var(--cipher-muted);
  pointer-events: none;
}
.chevron {
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
}
.trigger {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--cipher-space-control-gap);
  text-align: start;
  white-space: nowrap;
}
@media (hover: hover) {
  .triggerHover:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--cipher-action-outline-hover);
  }
}
.triggerHover[aria-expanded="true"] {
  background-color: var(--cipher-action-outline-hover);
}
.trigger > :first-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger > .leading {
  flex: none;
}
.trigger > .leading + * {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger [data-placeholder],
.trigger[data-placeholder] > :first-child,
.trigger[data-placeholder] > .leading + * {
  color: var(--cipher-muted);
}
.textarea {
  min-height: calc(2 * var(--cipher-space-32));
  field-sizing: content;
  resize: vertical;
}
/* field-sizing: content ignores the rows attribute, so rows becomes the starting height: that many lines plus the field's padding and border, and content still grows it. */
.textarea::placeholder {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.textarea[data-rows] {
  min-height: calc(
    var(--cipher-textarea-rows) * 1lh + var(--cipher-field-height) -
      var(--cipher-type-body-line-height)
  );
}
.textarea[data-max-rows] {
  --cipher-textarea-cap: calc(
    var(--cipher-textarea-max-rows) * 1lh + var(--cipher-field-height) -
      var(--cipher-type-body-line-height)
  );
  min-height: min(calc(2 * var(--cipher-space-32)), var(--cipher-textarea-cap));
  max-height: var(--cipher-textarea-cap);
  overflow-y: auto;
}
.textarea[data-rows][data-max-rows] {
  min-height: min(
    calc(
      var(--cipher-textarea-rows) * 1lh + var(--cipher-field-height) -
        var(--cipher-type-body-line-height)
    ),
    var(--cipher-textarea-cap)
  );
}
.textarea[data-mono] {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  tab-size: 2;
}
.searchRow {
  display: flex;
  min-height: var(--cipher-size-control-lg);
  align-items: center;
  gap: var(--cipher-space-8);
  padding-inline: calc(var(--cipher-space-menu-inset) + var(--cipher-space-8));
  /* lint-css-allow: single-row: the one search field above a menu's options */
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  color: var(--cipher-muted);
  cursor: text;
}
.searchRow:focus-within {
  color: var(--cipher-ink);
}
.searchRow > svg {
  flex: none;
  pointer-events: none;
}
.searchRow > input {
  flex: 1 1 auto;
