  pointer-events: auto;
}
:is(.option, .createOption)[data-wrap] > .optionLabel,
.option[data-wrap][data-description="stacked"] > span > .optionLabel {
  overflow-wrap: anywhere;
  white-space: normal;
}
.createOption {
  --cipher-lead-line: var(--cipher-type-body-line-height);
}
.createOption > .optionBox {
  --cipher-lead-size: calc(var(--cipher-size-icon) + 2 * var(--cipher-size-control-border));
}
.optionGlob {
  font-family: var(--cipher-font-mono);
}
.optionMeta {
  flex: 0 0 auto;
  min-width: 0;
  max-width: 50%;
  overflow: hidden;
  color: var(--cipher-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
}
.option[data-description="stacked"] {
  align-items: flex-start;
}
.option[data-description="stacked"] > .optionCheck {
  height: var(--cipher-type-body-line-height);
}
.optionDescription {
  display: block;
}
.optionCheck {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
}
.optionCheck svg {
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
}
.optionBox {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: calc(var(--cipher-size-icon) + 2 * var(--cipher-size-control-border));
  height: calc(var(--cipher-size-icon) + 2 * var(--cipher-size-control-border));
  border-radius: 0;
}
[aria-disabled="true"] > .optionBox {
  border-color: var(--cipher-line-soft);
  background-color: var(--cipher-line-soft);
  color: var(--cipher-faint);
}
[aria-disabled="true"] > .optionBox[data-state="checked"] {
  border-color: var(--cipher-control);
  background-color: var(--cipher-control);
  color: var(--cipher-surface);
}
.quickBar {
  box-sizing: content-box;
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-2);
  height: var(--cipher-size-control-md);
  padding-inline: var(--cipher-space-10) var(--cipher-space-4);
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.quickStatus {
  flex: 1 1 auto;
  min-width: 0;
  margin-inline-end: var(--cipher-space-8);
  overflow: hidden;
  color: var(--cipher-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
}
.commandText {
  flex-direction: row;
  align-items: baseline;
  gap: var(--cipher-space-8);
}
.commandText > :first-child {
  flex: none;
  max-width: 100%;
}
.pathAnchor {
  width: 100%;
  min-width: 0;
}
.pathList {
  width: var(--radix-popover-trigger-width);
}
.panelColumn {
  display: flex;
  flex-direction: column;
}
.panelColumn > [data-slot="popover-scroll"] {
  display: flex;
  flex-direction: column;
}
.panelColumn > [data-slot="popover-scroll"] > * {
  flex: none;
}
.panelColumn > [data-slot="popover-scroll"] > [role="listbox"] {
  flex: 0 1 auto;
  min-height: 0;
}
